def main():
    rows = json.loads(PATH.read_text(encoding="utf-8"))
    for row_id, template in TEMPLATES.items():
        row = rows[str(row_id)]
        if row["translation"]:
            continue
        tags = re.findall(r"<hex:[0-9A-Fa-f]+>", row["original"])
        slots = list(re.finditer(r"\{@(\d+)\}", template))
        assert [int(match.group(1)) for match in slots] == list(range(len(tags))), row_id
        row["translation"] = re.sub(
            r"\{@(\d+)\}", lambda match: tags[int(match.group(1))], template
        )
    for row_id, translation in SHORT_TEXT.items():
        row = rows[str(row_id)]
        if not row["translation"]:
            assert len(translation.split("<hex:")) == len(row["original"].split("<hex:")), row_id
            row["translation"] = translation
    for row_id, translation in MAHJONG.items():
        row = rows[str(row_id)]
        if row["translation"]:
            continue
        assert len(translation.split("<hex:")) == len(row["original"].split("<hex:")), row_id
        row["translation"] = translation
    for row in rows.values():
        if not row["translation"] and row["original"] in HEADINGS:
            row["translation"] = HEADINGS[row["original"]]
        if not row["translation"] and row["original"] in MORE_HEADINGS:
            row["translation"] = MORE_HEADINGS[row["original"]]
    PATH.write_text(json.dumps(rows, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")


if __name__ == "__main__":
    main()
